-- Additive original-objective daily hunter target authority. No NPC activation.
-- Existing50 public contracts, Modulox62 and immutable room plans are unchanged.
CREATE TABLE recurring_hunter_native_target_authority (
 definition_id integer NOT NULL, version integer NOT NULL,
 boss_reference integer NOT NULL CHECK(boss_reference>0),
 dungeon_definition_id integer NOT NULL CHECK(dungeon_definition_id>0),
 route_key text NOT NULL CHECK(length(route_key)>0),
 route_policy_version integer NOT NULL CHECK(route_policy_version>0),
 final_room_order integer NOT NULL CHECK(final_room_order>0),
 category_id integer NOT NULL CHECK(category_id>0),
 minimum_level integer NOT NULL CHECK(minimum_level BETWEEN 1 AND 245),
 minimum_level_authority text NOT NULL CHECK(minimum_level_authority='wakemu-reconstruction:original-native-category-bracket-minimum'),
 native_catalog_revision text NOT NULL, monsters_path text NOT NULL, monsters_sha256 text NOT NULL,
 plan_sha256 text NOT NULL CHECK(plan_sha256 ~ '^[0-9a-f]{64}$'),
 interpretation_policy text NOT NULL CHECK(interpretation_policy='wakemu.daily-hunter-native-objective-final-room-v1'),
 reward_policy text NOT NULL CHECK(reward_policy='fixed-native-parameter-no-booster'),
 native_property_id integer NOT NULL CHECK(native_property_id=43),
 source_authority text NOT NULL CHECK(length(source_authority)>0),
 proof_sha256 text NOT NULL CHECK(proof_sha256 ~ '^[0-9a-f]{64}$'),
 native_reward_order integer[] NOT NULL CHECK(cardinality(native_reward_order)=2),
 provenance jsonb NOT NULL CHECK(jsonb_typeof(provenance)='object'),
 PRIMARY KEY(definition_id,version,boss_reference), UNIQUE(definition_id,version),
 FOREIGN KEY(definition_id,version,boss_reference) REFERENCES recurring_hunter_targets,
 FOREIGN KEY(native_catalog_revision,monsters_path,monsters_sha256)
  REFERENCES recurring_hunter_catalog_sources(native_catalog_revision,monsters_path,monsters_sha256)
);
CREATE TABLE recurring_hunter_native_target_occurrences (
 definition_id integer NOT NULL, version integer NOT NULL,
 monster_index integer NOT NULL CHECK(monster_index>=0),
 planned_role text NOT NULL CHECK(planned_role IN('boss','monster','unknown')),
 count integer NOT NULL CHECK(count>0),
 PRIMARY KEY(definition_id,version,monster_index),
 FOREIGN KEY(definition_id,version) REFERENCES recurring_hunter_native_target_authority(definition_id,version)
);
CREATE TRIGGER recurring_hunter_native_target_authority_immutable
 BEFORE UPDATE OR DELETE ON recurring_hunter_native_target_authority
 FOR EACH ROW EXECUTE FUNCTION recurring_hunter_immutable_source();
CREATE TRIGGER recurring_hunter_native_target_occurrence_immutable
 BEFORE UPDATE OR DELETE ON recurring_hunter_native_target_occurrences
 FOR EACH ROW EXECUTE FUNCTION recurring_hunter_immutable_source();
CREATE OR REPLACE FUNCTION recurring_hunter_daily_member_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'Daily hunter member is immutable'; END IF;
 PERFORM 1 FROM recurring_hunter_daily_pools WHERE pool_version=NEW.pool_version AND NOT sealed FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Daily hunter pool is sealed'; END IF;
 PERFORM 1 FROM recurring_hunter_contracts c WHERE c.definition_id=NEW.definition_id AND c.version=NEW.version
 AND c.period_ms=86400000 AND (
 EXISTS(SELECT 1 FROM recurring_hunter_target_authority a WHERE a.definition_id=c.definition_id AND a.version=c.version AND a.category_id=NEW.category_id)
 OR EXISTS(SELECT 1 FROM recurring_modulox_authority a WHERE a.definition_id=c.definition_id AND a.version=c.version AND a.category_id=NEW.category_id)
 OR EXISTS(SELECT 1 FROM recurring_hunter_native_target_authority a WHERE a.definition_id=c.definition_id AND a.version=c.version AND a.category_id=NEW.category_id));
 IF NOT FOUND THEN RAISE EXCEPTION 'Daily hunter member lacks qualified daily authority'; END IF;
 RETURN NEW;
END $$;

UPDATE recurring_hunter_daily_pools SET sealed=true WHERE pool_version=E'wakemu.daily-hunter65-modulox64-v1';
UPDATE recurring_hunter_daily_active SET pool_version=E'wakemu.daily-hunter65-modulox64-v1',enabled=false WHERE singleton;
